  "implementation": "def solve(case):
    import json
    # Extract payload safely
    if 'payload' in case:
        payload = case['payload']
    else:
        payload = case
    round_scores = payload['round_scores']
    round_targets = payload['round_targets']
    forced = payload['forced']
    # Validate structure
    if not round_scores or not round_targets:
        raise ValueError('Empty round_scores or round_targets')
    num_rounds = len(round_scores)
    if len(round_targets) != num_rounds:
        raise ValueError('Mismatch between round_scores and round_targets lengths')
    N = len(round_scores[0])
    for scores in round_scores:
        if len(scores) != N:
            raise ValueError('Inconsistent score lengths')
    forced_set = set()
    for idx in forced:
        if idx < 0 or idx >= N:
            raise ValueError(f'Forced index {idx} out of range')
        if idx in forced_set:
            raise ValueError('Duplicate forced index')
        forced_set.add(idx)
    # Simulate rounds
    active = [True] * N
    masks = []
    for r in range(num_rounds):
        active_indices = [i for i in range(N) if active[i]]
        # Check forced are present
        for f in forced:
            if not active[f]:
                raise ValueError(f'Forced index {f} not active in round {r}')
        target = round_targets[r]
        if target < len(forced):
            raise ValueError(f'Round {r} target {target} less than forced count {len(forced)}')
        if target > len(active_indices):
            raise ValueError(f'Round {r} target {target} exceeds active count {len(active_indices)}')
        # Keep forced and decide additional tokens
        keep = set(forced)
        needed = target - len(forced)
        candidates = [i for i in active_indices if i not in forced_set]
        scores_r = round_scores[r]
        candidates.sort(key=lambda i: (-scores_r[i], i))
        selected = candidates[:needed]
        keep.update(selected)
        new_active = [False] * N
        for i in keep:
            new_active[i] = True
        masks.append(new_active)
        active = new_active
    final_indices = sorted([i for i in range(N) if active[i]])
    return {
        'masks': masks,
        'final_indices': final_indices
    }"
